def Saisie_msg():
    b = False
    while not b:
        ch = str(input(('Donner le message à crypter: ')))
        b = verif(ch)
    return ch, len(ch)


def verif(ch):
    i = -1
    ok = True
    while ok and i < len(ch) - 1:
        i += 1
        ok = "A" <= ch[i] <= "Z" or ch[i] == ' '
    return ok


def Saisie_clé(n):
    b = False
    while not b:
        ch = (input('Donner la clé du cryptage: '))
        b = ch.isnumeric() and len(ch) == n
    return ch


def Cryptage(msg, clé, n):
    R = ''
    for i in range(n):
        if msg[i] != ' ':
            if "A" <= chr(ord(msg[i]) + int(clé[i])) <= "Z":
                R += chr(ord(msg[i]) + int(clé[i]))
            else:
                R += chr(ord(msg[i]) + int(clé[i]) - 26)

        else:
            R += msg[i]
    return R


